const emails = [
  { id: 1, from: "customer1@example.com", subject: "Complaint about order 1042", text: "The goods arrived damaged, I want a refund. This is urgent." },
  { id: 2, from: "customer2@example.com", subject: "Billing question", text: "Can you send me a duplicate invoice for September?" },
  { id: 3, from: "partner@example.com", subject: "Partnership", text: "We would like to introduce our service and arrange a meeting." },
  { id: 4, from: "customer3@example.com", subject: "Cannot log in", text: "After changing my password I cannot log in to my account." }
];
return emails.map(e => ({ json: e }));

const rules = [
  { queue: "complaints", words: ["complaint", "damaged", "refund"] },
  { queue: "billing", words: ["invoice", "payment", "billing", "credit note"] },
  { queue: "tech-support", words: ["log in", "password", "not working", "error"] },
  { queue: "sales", words: ["partnership", "offer", "meeting"] }
];
return $input.all().map(({ json }) => {
  const t = (json.subject + " " + json.text).toLowerCase();
  const match = rules.find(r => r.words.some(w => t.includes(w)));
  const urgent = ["urgent", "immediately", "asap"].some(w => t.includes(w));
  return { json: {
    ...json,
    queue: match ? match.queue : "manual-review",
    priority: urgent ? "high" : "normal",
    // Anything uncertain or urgent always goes to a human.
    human_review: !match || urgent
  } };
});
